MAX_PASSOS = 8

def rodar_agente(objetivo, usuario):
    contexto = [sistema(), objetivo]
    for passo in range(MAX_PASSOS):
        saida = llm(contexto, ferramentas=FERRAMENTAS_PERMITIDAS[usuario.papel])
        trace(passo, saida)
        if not saida.chamadas:
            return saida.texto
        for chamada in saida.chamadas:
            validar_schema(chamada)
            if chamada.nome in ACOES_SENSIVEIS:
                return pedir_confirmacao(usuario, chamada)
            contexto.append(executar_com_timeout(chamada, segundos=10))
    return escalar_para_humano(objetivo, contexto)
